test "can create complex tree" {
    var tree = Tree.init(testing.allocator);
    defer tree.deinit();
    try tree.insert(4);
    try tree.insert(2);
    try tree.insert(6);
    try tree.insert(1);
    try tree.insert(3);
    try tree.insert(5);
    try tree.insert(7);
    if (tree.root) |o| {
        try testing.expectEqual(4, o.data);
